--- a/src/Reports/DailyVisits.php
+++ b/src/Reports/DailyVisits.php
@@ -1,18 +1,40 @@
 <?php

 namespace Clinic\Reports;

 final class DailyVisits
 {
     public function __construct(private \PDO $db) {}

+    public function forDay(string $day): array
+    {
+        $visits = $this->db
+            ->prepare('SELECT id, pet_id, owner_id, starts_at FROM visits WHERE day = ?');
+        $visits->execute([$day]);
+
+        $rows = [];
+        foreach ($visits->fetchAll() as $visit) {
+            $owner = $this->db->prepare('SELECT phone FROM owners WHERE id = ?');
+            $owner->execute([$visit['owner_id']]);
+
+            $rows[] = $visit + ['phone' => $owner->fetchColumn()];
+        }
+
+        return $rows;
+    }
 }
